let storageKey="footpath-v1";let state;try{state=JSON.parse(localStorage.getItem('footpath-v1'))}catch{}state=state&&Array.isArray(state.units)?state:{target:50,units:lessons.map(()=>({attempts:0,correct:0,history:[],read:[],passed:false,due:0,misses:[]}))};state.target=state.target===60?60:50;lessons.forEach((_,i)=>{state.units[i]??={attempts:0,correct:0,history:[],read:[],passed:false,due:0,misses:[]}});
let view='path',filter='all',selected=0,tab='map',readingIndex=0,readingCheck=0,question=null,answered=false,test=null,reviewMode=false,installPrompt;
const $=s=>document.querySelector(s), escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{toast('Storage unavailable. Keep this page open and export a backup.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function unlocked(i){return i===0||state.units[i-1].passed}function current(){return Math.min(lessons.findIndex((_,i)=>!state.units[i].passed)<0?9:lessons.findIndex((_,i)=>!state.units[i].passed),9)}
function totals(){return state.units.reduce((a,u)=>({attempts:a.attempts+u.attempts,correct:a.correct+u.correct,passed:a.passed+Number(u.passed)}),{attempts:0,correct:0,passed:0})}
function stats(){let t=totals();return `<div class="stats"><div class="stat"><span class="symbol">↗</span><div><strong>${t.passed}<span class="sub"> / 10</span></strong><small>Milestones mastered</small></div></div><div class="stat"><span class="symbol">↻</span><div><strong>${t.attempts}</strong><small>School-path attempts</small></div></div><div class="stat"><span class="symbol">✳</span><div><strong>${t.attempts?Math.round(t.correct/t.attempts*100):0}%</strong><small>School-path accuracy</small></div></div></div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='path')renderPath();if(view==='lesson')renderLesson();if(view==='review')renderReview();if(view==='progress'){renderProgress();renderProgressExtras()}if(view==='guide')renderGuide();if(view==='workshop')renderWorkshop();if(view==='ielts')renderIELTS();}
function renderPath(){const i=current(),l=lessons[i];$('#main').innerHTML=`<div class="titlebar"><div><div class="eyebrow">ONE SMALL STEP AT A TIME</div><h1>Your English adventure starts here.</h1><p class="sub">Learn it. Read it. Practise it. Make it yours. <span lang="zh">循序渐进，学以致用。</span></p></div><span class="pill">✳ Grade 3 → IELTS 7.0+</span></div><section class="hero"><div class="herocopy"><div class="eyebrow">YOUR NEXT LITTLE STEP · GRADE ${l.grade}</div><h2>${l.name}.<br>A little more confidence.</h2><p>Explore a knowledge map, meet the language in stories, and make it stick through practice.</p><button class="primary" data-open="${i}">Start learning <span aria-hidden="true">↗</span></button></div><div class="landscape" aria-hidden="true"><div class="sun"></div><div class="hill back"></div><div class="hill"></div><div class="trail"></div><div class="hill front"></div><div class="plant">⚑</div><div class="journeylabel">GROW AT YOUR OWN PACE</div></div></section>${stats()}<section><div class="sectionhead"><div><h2>A path that grows with you</h2><p>10 starter milestones · 30 original readings · a steady climb</p></div><select id="target" aria-label="Repetition target"><option value="50" ${state.target===50?'selected':''}>50 repetitions / lesson</option><option value="60" ${state.target===60?'selected':''}>60 repetitions / lesson</option></select></div><div class="stagebar">${[['all','All stages'],['primary','Primary 小学'],['junior','Junior high 初中'],['senior','Senior high 高中']].map(([k,v])=>`<button data-filter="${k}" class="${filter===k?'selected':''}">${v}</button>`).join('')}</div><div class="pathlist">${lessons.filter(l=>filter==='all'||filter==='primary'&&l.grade<=6||filter==='junior'&&l.grade>=7&&l.grade<=9||filter==='senior'&&l.grade>=10).map(l=>{let u=state.units[l.id],open=unlocked(l.id);return `<article class="lessoncard ${l.id===i?'current':''}"><div class="lessonnum">${u.passed?'✓':String(l.id+1).padStart(2,'0')}</div><div><div class="lessonmeta">GRADE ${l.grade}${l.grade>=10?' · 高'+(l.grade-9):''}<span class="badge">${u.passed?'MASTERED':open?'READY TO GROW':'COMING UP'}</span></div><h3>${l.name}</h3><p>${l.grammar} · ${l.zh}</p></div><div class="lessonaction"><button data-open="${l.id}" class="${open?'primary':''}">${u.passed?'Revisit lesson':open?'Explore lesson ↗':'View preview ♧'}</button><small>${Math.min(u.attempts,state.target)} / ${state.target} repetitions · 3 readings</small></div></article>`}).join('')}</div></section><section class="panel"><div class="eyebrow">BEYOND SENIOR HIGH</div><h2>Your next destination: Academic IELTS 7.0+</h2><p class="sub">Evidence, precise vocabulary and four-skill practice. A separate advanced bridge follows the school pathway.</p><button class="primary" data-view="ielts">Explore the IELTS bridge ↗</button></section><div class="note"><span>✧</span><div><b>Understanding grows with repetition.</b><br>Finish all 3 reading checks, complete ${state.target} retrieval attempts, and score at least 80% on the mastery check to unlock the next step. Preview any lesson along the way.</div></div>`}
function renderLesson(){const l=lessons[selected],u=state.units[selected],open=unlocked(selected);$('#main').innerHTML=`<button class="back" data-view="path">← Back to your path</button><div class="eyebrow">GRADE ${l.grade} · ${open?'YOUR LEARNING SPACE':'PREVIEW · COMPLETE THE PREVIOUS MILESTONE TO PRACTISE'}</div><h1>${l.name}</h1><p class="sub">${l.theme} · ${l.zh}</p><div class="progressbar"><i style="width:${Math.min(u.attempts/state.target*100,100)}%"></i></div><p class="sub" id="lesson-progress">${u.attempts} / ${state.target} retrieval attempts · ${u.read.length} / 3 reading checks · ${u.passed?'Mastered ✓':'Keep growing'}</p><p class="sub" id="category-progress">${categoryProgress(u)}</p><div class="tabs">${[['map','01 · Knowledge map'],['words','02 · Words & expressions'],['read','03 · Read & notice'],['practice','04 · Repeat & retrieve'],['test','05 · Mastery check']].map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'selected':''}">${v}</button>`).join('')}</div><div id="lessonbody"></div>`;if(tab==='map')$('#lessonbody').innerHTML=`<section class="panel"><div class="eyebrow">CONNECT THE IDEAS</div><h2>One idea. A few useful branches.</h2><div class="map"><div class="mapcenter">${l.grammar}</div>${l.branches.map((s,i)=>`<div class="branch"><b>Branch ${i+1}</b>${escape(s)}</div>`).join('')}</div><p lang="zh">${l.explain}</p><div class="feedback"><b>See it in a sentence</b><br>${l.example}</div><button class="primary" data-tab="words" style="margin-top:20px">Connect words & expressions →</button></section>`;if(tab==='words')renderLanguage();if(tab==='read')renderReading();if(tab==='practice')startPractice();if(tab==='test')renderTest();}
const vocab=[['friend','朋友','ready','准备好的'],['routine','惯例','quiet','安静的'],['vegetable','蔬菜','wait','等待'],['audience','观众','teamwork','团队合作'],['compare','比较','useful','有用的'],['encourage','鼓励','neighbourhood','社区'],['recycle','回收利用','display','展出'],['guidance','指导','accessible','易理解的；无障碍的'],['evidence','证据','assumption','假设'],['scrutiny','仔细审查','bias','偏差']];
function highlight(text){const patterns=[/\b(am|is|are)\b/g,/\b(gets|reads|plays|likes|waters|checks|gives|walks|does)\b/g,/\b(am|is|are) \w+ing\b/g,/\b(visited|fed|picked|showed|went|lost|looked|found|called|thanked|performed|forgot|helped|learned|mattered)\b/g,/\b(shorter|busier|quieter|cheaper|more useful|more enjoyable|better)\b/g,/\b(have|has) (just |not )?\w+\b/g,/\b(is|are|was|were|be) (\w+ed|taken|used|sent)\b/g,/\b(who|whose|that|which|where)\b/g,/\b(whether|that|What|what|how)\b/g,/\b(would|could|might|had|Had|If|if)\b/g];return escape(text).replace(patterns[selected],'<mark>$&</mark>')}
function renderReading(){const l=lessons[selected],r=l.readings[readingIndex],u=state.units[selected],v=vocab[selected];const rq=readingQuestions(l)[readingCheck];$('#lessonbody').innerHTML=`<div class="readingtools">${l.readings.map((r,i)=>`<button data-reading="${i}" ${i===readingIndex?'style="background:#eaf0dc"':''}>${u.read.includes(i)?'✓ ':''}${i+1}. ${r[0]}</button>`).join('')}</div><article class="panel"><div class="eyebrow">READING ${readingIndex+1} OF 3 · ORIGINAL PRACTICE TEXT</div><h2>${r[0]}</h2><div class="readingtools"><button id="speak">▷ Listen</button><button id="stop-speak">Stop audio</button></div><p class="reading">${highlight(r[1])}</p><p class="sub">Highlighted language shows the target grammar or its signal words. Audio uses your device’s available English voice.</p><div class="feedback"><b>Word connections · 词汇</b><br>${v[0]} — ${v[1]} &nbsp; / &nbsp; ${v[2]} — ${v[3]}<br><b>Useful pattern:</b> ${l.example}</div><h3>Apply what you learned · ${readingCheck+1} / 3</h3><p>${rq.prompt}</p><div class="options" id="readoptions">${shuffle(rq.options).map(a=>`<button class="option" data-read-answer="${escape(a)}">${escape(a)}</button>`).join('')}</div><div id="readfeedback" role="status"></div></article>`;}
function readingQuestions(l){const r=l.readings[readingIndex],v=vocab[selected];return [{prompt:r[2],answer:r[3],options:[r[3],r[4]],why:r[1]},{prompt:l.cloze,answer:l.answer,options:[l.answer,...l.wrong],why:l.explain},{prompt:`Which word means ‘${v[1]}’?`,answer:v[0],options:[v[0],v[2]],why:`${v[0]} — ${v[1]}; ${v[2]} — ${v[3]}`}]}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function corePool(l){return [{prompt:l.cloze,answer:l.answer,options:[l.answer,...l.wrong],why:l.explain,type:'grammar'},...l.readings.map(r=>({prompt:`${r[0]}: ${r[2]}`,context:r[1],answer:r[3],options:[r[3],r[4]],why:`Read again: ${r[1]}`,type:'reading'})),{prompt:`Type the missing word(s): ${l.cloze}`,answer:l.answer,why:l.explain,type:'typed'}]}
function pool(l){return [...corePool(l),...languagePool(l)].map(q=>({...q,category:q.category||(q.type==='reading'?'reading':q.type==='vocabulary'?'vocabulary':q.type==='expression'?'expression':'grammar')}))}
const categoryTargets={grammar:15,vocabulary:15,expression:10,reading:10};
function categoryReady(u){return Object.entries(categoryTargets).every(([k,n])=>(u.categories?.[k]||0)>=n)}
function categoryProgress(u){return Object.entries(categoryTargets).map(([k,n])=>`${k}: ${u.categories?.[k]||0}/${n}`).join(' · ')}
function pickQuestion(){let u=state.units[selected],p=pool(lessons[selected]);let prior=question?.prompt;let candidates=p.filter(q=>q.prompt!==prior);const needed=Object.entries(categoryTargets).filter(([k,n])=>(u.categories?.[k]||0)<n).sort((a,b)=>(u.categories?.[a[0]]||0)/a[1]-(u.categories?.[b[0]]||0)/b[1]);if(needed.length){const focused=candidates.filter(q=>q.category===needed[0][0]);if(focused.length)candidates=focused;}if(u.misses.length&&Math.random()<.5){let missed=candidates.filter(q=>u.misses.includes(q.prompt));if(missed.length)candidates=missed}return candidates[Math.floor(Math.random()*candidates.length)]}
function startPractice(){if(!unlocked(selected)){$('#lessonbody').innerHTML='<div class="panel">Preview the map and readings now. Complete the previous milestone to unlock scored practice.</div>';return}test=null;question=pickQuestion();answered=false;renderQuestion();}
function questionHTML(q){return `<p class="sub">${(q.type==='typed'||q.type==='expression')?'Recall without answer choices':'Choose the best answer'}</p>${q.context?`<p>${q.context}</p>`:''}<h2>${escape(q.prompt)}</h2>${(q.type==='typed'||q.type==='expression')?'<form id="answerform"><label class="screenreader" for="typed">Your answer</label><input id="typed" type="text" autocomplete="off" placeholder="Type your answer…" required><button class="primary">Check answer →</button></form>':`<div class="options">${shuffle(q.options).map(a=>`<button class="option" data-answer="${escape(a)}">${escape(a)}</button>`).join('')}</div>`}<div id="answerfeedback" role="status"></div>`}
function renderQuestion(){const u=state.units[selected];$('#lessonbody').innerHTML=`<section class="panel"><div class="eyebrow">${test?`MASTERY CHECK · ${test.answers.length+1} / 10`:`RETRIEVAL PRACTICE · ${u.attempts} / ${state.target}`}</div>${!test?`<p class="sub">Practising ${question.category} · balanced practice across all four categories.</p>`:''}${questionHTML(question)}</section>`;}
function submitAnswer(a){if(answered||!a.trim())return;answered=true;const ok=a.trim().toLowerCase()===question.answer.toLowerCase();if(test)test.answers.push(ok);else{const u=state.units[selected];u.attempts++;u.correct+=Number(ok);u.categories??={};u.categories[question.category]=(u.categories[question.category]||0)+1;u.history.push(ok);u.history=u.history.slice(-50);u.lastPractised=Date.now();u.due=Date.now()+(ok?86400000:600000);const topProgress=document.querySelector('#lesson-progress');if(topProgress)topProgress.textContent=`${u.attempts} / ${state.target} retrieval attempts · ${u.read.length} / 3 reading checks · ${u.passed?'Mastered ✓':'Keep growing'}`;const catProgress=document.querySelector('#category-progress');if(catProgress)catProgress.textContent=categoryProgress(u);if(!ok&&!u.misses.includes(question.prompt))u.misses.push(question.prompt);if(ok)u.misses=u.misses.filter(p=>p!==question.prompt);save()}document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;b.classList.add(b.dataset.answer===question.answer?'correct':b.dataset.answer===a?'incorrect':'none')});if($('#typed')){$('#typed').disabled=true;$('#answerform button').disabled=true}$('#answerfeedback').innerHTML=`<div class="feedback"><b>${ok?'✓ Well done.':'Let’s learn from this.'}</b><br>Answer: ${escape(question.answer)}<br>${escape(question.why)}</div><button class="primary" id="nextquestion" style="margin-top:18px">${test&&test.answers.length===10?'See my result':'Next question →'}</button>`;}
function renderTest(){const u=state.units[selected];if(!unlocked(selected)||u.attempts<state.target||u.read.length<3||!categoryReady(u)){$('#lessonbody').innerHTML=`<div class="panel"><h2>Build a strong foundation first.</h2><p>Complete all three reading checks and ${state.target} retrieval attempts before your 10-question mastery check.</p><p>${u.read.length}/3 reading checks · ${u.attempts}/${state.target} attempts</p><p class="sub">${categoryProgress(u)}</p><p>All four practice categories must reach their minimum, as well as the total target.</p><button class="primary" data-tab="${u.read.length<3?'read':'practice'}">Keep learning →</button></div>`;return}$('#lessonbody').innerHTML=`<div class="panel"><h2>Ready to make this step yours?</h2><p>10 questions, including recall without choices. Score 8/10 or higher to unlock the next milestone. Feedback appears after the full check.</p><button class="primary" id="starttest">Begin mastery check →</button></div>`;}
function beginTest(){let l=lessons[selected],p=corePool(l),lp=languagePool(l);test={answers:[],questions:shuffle([p[0],p[4],...shuffle(p.slice(1,4)).slice(0,2),...shuffle(lp.filter(q=>q.type==='vocabulary')).slice(0,4),...lp.filter(q=>q.type==='expression').slice(0,2)])};question=test.questions[0];answered=false;renderQuestion();}
function submitTestAnswer(a){if(answered||!a.trim())return;answered=true;test.answers.push(a.trim().toLowerCase()===question.answer.toLowerCase());test.responses??=[];test.responses.push({q:question.prompt,a,answer:question.answer,why:question.why});if(test.answers.length===10){const score=test.answers.filter(Boolean).length,u=state.units[selected];if(score>=8){u.passed=true;u.due=Date.now()+86400000;save()}$('#lessonbody').innerHTML=`<section class="panel"><div class="eyebrow">YOUR MASTERY CHECK</div><h1>${score} / 10 ${score>=8?'✳':''}</h1><h2>${score>=8?'A little step. A real achievement.':'You’re still growing.'}</h2><p>${score>=8?(selected===9?'You have completed all starter milestones. Keep reviewing to retain what you know.':'Your next milestone is unlocked. Come back tomorrow for a spaced review.'):'Review the corrections below, then practise again before retrying.'}</p>${test.responses.map((r,i)=>`<details><summary style="padding:10px 0">${test.answers[i]?'✓':'↻'} ${escape(r.q)}</summary><p>Your answer: ${escape(r.a)}<br>Correct answer: ${escape(r.answer)}<br>${escape(r.why)}</p></details>`).join('')}<button class="primary" data-view="path" style="margin-top:20px">Back to my path →</button></section>`;test=null;}else{question=test.questions[test.answers.length];answered=false;renderQuestion()}}
function renderReview(){const due=lessons.filter((l,i)=>state.units[i].attempts&&state.units[i].due<=Date.now());const mistakes=lessons.filter((l,i)=>state.units[i].misses.length);$('#main').innerHTML=`<div class="eyebrow">MAKE THE LEARNING LAST</div><h1>A little practice, a stronger memory.</h1><p class="sub">Revisit mistakes now. Return tomorrow for spaced recall.</p>${stats()}<div class="columns"><section class="panel"><h2>Ready for review · ${due.length}</h2>${due.length?due.map(l=>`<p>${l.grammar}</p><button class="primary" data-practice="${l.id}">Review Grade ${l.grade} →</button>`).join(''):'<p class="sub">No scheduled reviews due yet. Correct answers schedule a review for tomorrow; mistakes return sooner.</p>'}</section><section class="panel"><h2>Give these another try · ${mistakes.length}</h2>${mistakes.length?mistakes.map(l=>`<p>${l.grammar} · ${state.units[l.id].misses.length} questions to revisit</p><button class="secondary" data-practice="${l.id}">Practise again ↻</button>`).join(''):'<p class="sub">Missed questions will appear here. Getting something wrong is a useful part of learning.</p>'}</section></div><button class="primary" data-practice="${current()}">Continue my current lesson →</button>`}
function renderProgress(){$('#main').innerHTML=`<div class="eyebrow">EVERY ATTEMPT IS A STEP</div><h1>Look how far you’re growing.</h1><p class="sub">Progress stays in this browser on this device. Export a backup to transfer it to another phone.</p>${stats()}<div class="panel">${lessons.map(l=>{let u=state.units[l.id];return `<div><div class="sectionhead"><h3>Grade ${l.grade} · ${l.grammar}</h3><span class="sub">${u.attempts} attempts · ${u.correct} correct ${u.passed?'· ✓ Mastered':''}</span></div><div class="progressbar"><i style="width:${Math.min(u.attempts/state.target*100,100)}%"></i></div></div>`}).join('')}</div><div class="readingtools"><button id="export">Export progress ↓</button><button id="import">Import progress ↑</button><button id="download">Download app source ↓</button></div><input type="file" id="importfile" accept="application/json" hidden>`}
function renderGuide(){$('#main').innerHTML=`<div class="eyebrow">A THOUGHTFUL WAY TO LEARN</div><h1>Small steps, built on understanding.</h1><div class="panel guide"><h2>The learning loop</h2><ol><li><b>Connect:</b> explore a grammar map with Chinese explanations and English examples.</li><li><b>Notice:</b> read three original texts and answer a meaning question for each.</li><li><b>Retrieve:</b> complete 50 or 60 scored attempts, mixing grammar, comprehension and typed recall.</li><li><b>Check:</b> reach 80% on a ten-question check before the next milestone unlocks.</li><li><b>Return:</b> revisit errors and practise again on later days.</li></ol><p>Each lesson also includes a thematic word network, meaning contrasts, collocations, example sentences and reusable expressions. These appear in retrieval practice and the mastery check.</p><p>The repetition target is your learning preference, not a scientifically guaranteed number for mastery. Repeated questions can become familiar; lasting learning needs varied examples, delayed recall and real language use. This starter uses a small question bank and does not measure overall English proficiency.</p><h2>How the curriculum informs this path</h2><p>China’s 2022 compulsory-education English standard describes three main attainment bands: Grades 3–4, 5–6 and 7–9. Senior high builds towards richer language use, discourse, cultural understanding and reasoning. The grade-by-grade grammar sequence here is an editorial scaffold, not an official textbook sequence.</p><p>This first release contains one representative grammar milestone per grade. It is a working starting point, not the full Grade 3–12 curriculum. Phonics, pronunciation, broader vocabulary, listening, speaking, writing and additional grammar units need a larger reviewed course library.</p><h3>Grade 7 question research</h3><p>The Grade 7 workshop breaks the sample-paper demands into smaller skills. An anonymised analysis of the provided screenshots and links to Chinese sample-paper research are included in <a href="grade7-analysis.html">the research report</a>. The practice questions are original; photographs and personal details are not published.</p><h3>Research sources</h3><ul><li><a href="https://www.moe.gov.cn/srcsite/A26/s8001/202204/t20220420_619921.html" target="_blank" rel="noopener">Ministry of Education · 2022 compulsory curriculum release</a></li><li><a href="https://www.ictr.edu.cn/download_center/ywjy/p/1.html" target="_blank" rel="noopener">Institute of Curriculum and Textbook Research · official standards library</a></li><li><a href="https://www.pep.com.cn/xw/zt/rjwy/gzkb2020/202205/P020220517522153664167.pdf" target="_blank" rel="noopener">People’s Education Press · Senior High English standard (2017 / 2020 revision)</a></li></ul><p>Research consulted October 27, 2026. Sources are reference documents; stories and practice questions were authored for this app. The app has no affiliation with the Ministry or textbook publishers.</p><h2>Install on your phone</h2><p><b>iPhone:</b> open this website in Safari, tap Share, then Add to Home Screen. <b>Android:</b> open in Chrome and choose Install app or Add to Home screen from its menu. Installation options depend on browser support.</p><p>Open the app online once to cache the lessons. Your progress is stored locally and does not automatically sync between devices. Export a backup before clearing browser data.</p><button class="primary" id="download">Download app source ↓</button><p>App Store and Google Play publication requires a separate packaged mobile release and developer accounts. This release is an installable web app.</p></div>`}
function openLesson(i,t='map'){selected=i;tab=t;readingIndex=0;readingCheck=0;test=null;question=null;view='lesson';render();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;test=null;render();window.scrollTo(0,0)}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.open!==undefined)openLesson(Number(b.dataset.open));if(b.dataset.practice!==undefined)openLesson(Number(b.dataset.practice),'practice');if(b.dataset.tab){tab=b.dataset.tab;test=null;renderLesson()}if(b.dataset.reading!==undefined){readingIndex=Number(b.dataset.reading);readingCheck=0;renderReading()}if(b.dataset.readAnswer!==undefined){const l=lessons[selected],q=readingQuestions(l)[readingCheck],ok=b.dataset.readAnswer===q.answer;document.querySelectorAll('[data-read-answer]').forEach(x=>x.disabled=true);if(ok&&readingCheck===2&&unlocked(selected)){const u=state.units[selected];if(!u.read.includes(readingIndex))u.read.push(readingIndex);save()}$('#readfeedback').innerHTML=`<div class="feedback">${ok?'✓ Correct.':'Let’s look again.'} ${escape(q.why)}<br>${!unlocked(selected)?'Preview mode: reading checks are not saved.':ok&&readingCheck===2?'All three questions complete. Reading check saved.':''}</div><button class="primary" id="nextreadingcheck" data-ok="${ok}" style="margin-top:15px">${ok?(readingCheck===2?'Read again ↻':'Next question →'):'Try again ↻'}</button>`;}if(b.id==='nextreadingcheck'){if(b.dataset.ok==='true')readingCheck=(readingCheck+1)%3;renderReading();}if(b.dataset.answer!==undefined){if(test)submitTestAnswer(b.dataset.answer);else submitAnswer(b.dataset.answer)}if(b.id==='nextquestion'){if(test){question=test.questions[test.answers.length];answered=false;renderQuestion()}else startPractice()}if(b.id==='starttest')beginTest();if(b.id==='speak'){if(!('speechSynthesis' in window))return toast('Audio is unavailable in this browser.');speechSynthesis.cancel();const s=new SpeechSynthesisUtterance(lessons[selected].readings[readingIndex][1]);s.lang='en-GB';s.rate=.85;speechSynthesis.speak(s)}if(b.id==='stop-speak'&&'speechSynthesis'in window)speechSynthesis.cancel();if(b.id==='export'){const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'});downloadBlob(blob,'english-footpath-progress.json')}if(b.id==='import')$('#importfile').click();if(b.id==='download'){const a=document.createElement('a');a.href='english-footpath-source.zip';a.download='english-footpath-source.zip';a.click()}if(b.id==='install')installApp();if(b.classList.contains('close'))$('#modal').close()});
document.addEventListener('submit',e=>{if(e.target.id==='answerform'){e.preventDefault();if(test)submitTestAnswer($('#typed').value);else submitAnswer($('#typed').value)}});
document.addEventListener('change',async e=>{if(e.target.id==='target'){state.target=Number(e.target.value);save();render();toast('Repetition target updated. Previously mastered lessons stay open.')}if(e.target.id==='importfile'){try{const d=JSON.parse(await e.target.files[0].text());if(d.version!==1||![50,60].includes(d.target)||!Array.isArray(d.units)||d.units.length!==10)throw Error();d.units.forEach(u=>{if(!Number.isInteger(u.attempts)||u.attempts<0||!Number.isInteger(u.correct)||u.correct<0||u.correct>u.attempts||!Array.isArray(u.read)||u.read.some(i=>![0,1,2].includes(i))||!Array.isArray(u.misses)||u.misses.some(s=>typeof s!=='string')||!Array.isArray(u.history)||typeof u.passed!=='boolean')throw Error()});state={target:d.target,units:d.units};if(Array.isArray(d.workshop)&&d.workshop.length===6&&d.workshop.every(u=>Number.isInteger(u.attempts)&&u.attempts>=0&&Number.isInteger(u.correct)&&u.correct>=0&&u.correct<=u.attempts&&typeof u.passed==='boolean'))state.workshop=d.workshop;if(Array.isArray(d.ielts)&&d.ielts.length===4&&d.ielts.every(u=>Number.isInteger(u.attempts)&&u.attempts>=0&&Number.isInteger(u.correct)&&u.correct>=0&&u.correct<=u.attempts&&typeof u.passed==='boolean'))state.ielts=d.ielts;if(typeof d.workwriting==='string')state.workwriting=d.workwriting.slice(0,20000);if(d.ieltsDrafts&&typeof d.ieltsDrafts==='object')state.ieltsDrafts=Object.fromEntries(Object.entries(d.ieltsDrafts).filter(([k,v])=>['2','3'].includes(k)&&typeof v==='string').map(([k,v])=>[k,v.slice(0,30000)]));save();render();toast('Progress imported.')}catch{toast('That file is not a valid Footpath backup.')}}});
function downloadBlob(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});async function installApp(){if(installPrompt){await installPrompt.prompt();installPrompt=null;return}$('#modalbody').innerHTML='<div class="eyebrow">TAKE YOUR FOOTPATH WITH YOU</div><h2>A little learning, wherever you are.</h2><p><b>iPhone / iPad:</b> open this site in Safari → Share → Add to Home Screen.</p><p><b>Android:</b> open in Chrome → menu → Install app or Add to Home screen.</p><p class="sub">Visit online once before studying offline. Installation options depend on your browser.</p>';$('#modal').showModal()}
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});render();
function languagePool(l){const g=language[l.id];return [...g.words.map(w=>({prompt:`Choose the best word: ${w[5]}`,answer:w[0],options:g.words.map(x=>x[0]),why:`${w[0]} — ${w[1]}. ${w[2]} Example: ${w[4]}`,type:'vocabulary'})),...g.words.map(w=>({prompt:`Type the word meaning ‘${w[1]}’. Meaning clue: ${w[2]}`,answer:w[0],why:`${w[0]} — ${w[1]}. ${w[2]}`,type:'typed',category:'vocabulary'})),...g.expressions.map(x=>({prompt:`Complete the expression: ${x[3]}`,answer:x[4],why:`${x[0]} — ${x[1]}. ${x[2]}`,type:'expression'}))]}
function renderLanguage(){const g=language[selected];$('#lessonbody').innerHTML=`<section class="panel"><div class="eyebrow">A NETWORK OF MEANING</div><h2>${g.category}</h2><p>${g.insight}</p><div class="map"><div class="mapcenter">${g.category.split(' · ')[0]}</div>${g.words.map(w=>`<div class="branch"><b>${w[1]}</b><strong>${w[0]}</strong><p>${w[2]}</p><p class="collocation">${w[3]}</p><p><i>${w[4]}</i></p></div>`).join('')}</div><h2>Useful expressions · 学会整块表达</h2><div class="columns">${g.expressions.map(x=>`<article class="branch"><h3>${x[0]}</h3><b>${x[1]}</b><p>${x[2]}</p><p>${x[3].replace('___',`<strong>${x[4]}</strong>`)}</p></article>`).join('')}</div><div class="feedback"><b>Try making it yours · 迁移运用</b><p>${g.task}</p><p class="sub">Say it aloud or write it in a notebook. This open task is for practice; it is not automatically graded.</p></div><button class="primary" data-tab="read" style="margin-top:20px">Meet the language in a story →</button></section>`}

function renderProgressExtras(){const groups=[['Grade 7 microsteps',grade7steps,workshopState()],['IELTS 7.0+ bridge',ieltsStages,ieltsState()]];$('#main').innerHTML+=groups.map(([title,items,units])=>`<section class="panel"><h2>${title}</h2>${items.map((s,i)=>`<p><b>${i+1}. ${s.title}</b><br><span class="sub">${units[i].attempts}/${state.target} attempts · ${units[i].correct} correct · ${units[i].passed?'Mastered ✓':'In progress'}</span></p>`).join('')}</section>`).join('')}
